import math

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    H = int(data[0])
    W = int(data[1])
    N = int(data[2])

    bars = []
    index = 3
    for _ in range(N):
        R = int(data[index])
        C = int(data[index+1])
        L = int(data[index+2])
        bars.append((R, C, L))
        index += 3

    class SegmentTree:
        def __init__(self, size):
            self.n = 1
            while self.n < size:
                self.n <<= 1
            self.size = self.n
            self.tree = [0] * (2 * self.n)
            self.lazy = [None] * (2 * self.n)

        def push(self, node, l, r):
            if self.lazy[node] is not None:
                self.tree[node] = self.lazy[node]
                if l != r:
                    self.lazy[2*node] = self.lazy[node]
                    self.lazy[2*node+1] = self.lazy[node]
                self.lazy[node] = None

        def update_range(self, a, b, val, node=1, l=0, r=None):
            if r is None:
                r = self.n - 1
            self.push(node, l, r)
            if a > r or b < l:
                return
            if a <= l and r <= b:
                self.lazy[node] = val
                self.push(node, l, r)
                return
            mid = (l + r) // 2
            self.update_range(a, b, val, 2*node, l, mid)
            self.update_range(a, b, val, 2*node+1, mid+1, r)
            self.tree[node] = min(self.tree[2*node], self.tree[2*node+1])

        def query_range(self, a, b, node=1, l=0, r=None):
            if r is None:
                r = self.n - 1
            self.push(node, l, r)
            if a > r or b < l:
                return float('inf')
            if a <= l and r <= b:
                return self.tree[node]
            mid = (l + r) // 2
            left = self.query_range(a, b, 2*node, l, mid)
            right = self.query_range(a, b, 2*node+1, mid+1, r)
            return min(left, right)

    st = SegmentTree(W)

    for R, C, L in bars:
        c_start = C - 1
        c_end = C + L - 1 - 1
        st.update_range(c_start, c_end, R)

    results = []
    for R, C, L in bars:
        c_start = C - 1
        c_end = C + L - 1 - 1
        min_row = st.query_range(c_start, c_end)
        if min_row > R:
            new_row = min_row - 1
        else:
            new_row = H - 1
        results.append(new_row)
        st.update_range(c_start, c_end, new_row)

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
