    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    H = int(data[idx]); idx +=1
    W = int(data[idx]); idx +=1
    N = int(data[idx]); idx +=1

    bars = []
    min_row = [float('inf')] * (W + 2)  # columns 1..W
    for _ in range(N):
        R = int(data[idx]); idx +=1
        C = int(data[idx]); idx +=1
        L = int(data[idx]); idx +=1
        bars.append((R, C, L))

    # Initialize min_row
    for R, C, L in bars:
        for c in range(C, C + L):
            if R < min_row[c]:
                min_row[c] = R

    # Sort bars by row in descending order
    sorted_bars = sorted(bars, key=lambda x: -x[0])

    # For each bar, compute the new_row
    result = [0] * N
    for i in range(N):
        R, C, L = sorted_bars[i]
        min_block = float('inf')
        for c in range(C, C + L):
            if min_row[c] > R:
                if min_row[c] < min_block:
                    min_block = min_row[c]
        if min_block == float('inf'):
            steps = H - R
        else:
            steps = min_block - R - 1
        new_row = R + steps
        result[i] = new_row

        # Update min_row for the columns
        for c in range(C, C + L):
            if new_row + 1 < min_row[c]:
                min_row[c] = new_row + 1

    # Now, map the result back to the original order
    original_order = [0] * N
    for i in range(N):
        original_order[i] = result[i]

    for r in original_order:
        print(r)

